document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("vaga-form"),e=document.getElementById("lista-vagas"),t=document.getElementById("vaga-feedback");function a(){e.innerHTML="";const n=ForjaStorage.getVagas();0!==n.length?n.forEach(n=>{e.innerHTML+=`\n\n\n<div class="vaga-admin">\n\n\n<h3>\n${n.titulo}\n</h3>\n\n\n<p>\n${n.descricao}\n</p>\n\n\n<p>\n<strong>\nSetor:\n</strong>\n\n${n.setor}\n</p>\n\n\n\n<p>\n<strong>\nLocal:\n</strong>\n\n${n.local}\n</p>\n\n\n\n\n<button onclick="\nexcluirVaga(${n.id})\n">\n\nExcluir\n\n</button>\n\n\n</div>\n\n\n\n`}):e.innerHTML="\n\n<p>\nNenhuma vaga cadastrada.\n</p>\n\n"}n.addEventListener("submit",e=>{e.preventDefault();const o={titulo:document.getElementById("titulo").value,descricao:document.getElementById("descricao").value,setor:document.getElementById("setor").value,local:document.getElementById("local").value,status:"Aberta"};ForjaStorage.saveVaga(o),t.textContent="Vaga cadastrada com sucesso!",t.style.color="green",n.reset(),a()}),window.excluirVaga=n=>{confirm("Deseja excluir esta vaga?")&&(ForjaStorage.deleteVaga(n),a())},a()});